$_MODULE['<{vatnumber}prestashop>vatnumber_c2c74b135cab679a815e04b2a9d5eec0'] = 'Bevestigde nummers komen 30 dagen uit de lokale cache en worden elke 180 dagen opnieuw geverifieerd, omdat btw-registraties kunnen vervallen.';
$_MODULE['<{vatnumber}prestashop>vatnumber_d55032733add57a402d67e096c0bbd38'] = 'Kan de btw-status niet tonen: %s';
