$_MODULE['<{vatnumber}prestashop>vatnumber_d17a37903c2ff7ec71c5bae45d1e5a22'] = 'Datum in het formaat JJJJ-MM-DD, of leeg om alles te verifieren. Nummers in de wachtrij van klanten zonder adreswijziging en zonder bestelling sinds deze datum worden uit de verificatiewachtrij verwijderd. Handig na een upgrade van een shop met jarenlange oude adressen. Verwijderde nummers worden gewoon opnieuw live gecontroleerd als zo\'n klant ooit terugkomt.';
$_MODULE['<{vatnumber}prestashop>vatnumber_b9f5c797ebbf55adccdd8539a65a0241'] = 'Uitgeschakeld';
$_MODULE['<{vatnumber}prestashop>vatnumber_ac2f6a9cfa32070c4499f4879221058e'] = 'Uitgeschakeld (standaard): klanten krijgen de btw-vrijstelling direct, ook terwijl hun nummer nog op verificatie wacht. Ingeschakeld: klanten blijven btw betalen totdat VIES hun nummer heeft bevestigd. Ingeschakeld is veiliger voor u, uitgeschakeld is vriendelijker voor de klant. Alleen relevant wanneer automatische controle aan staat. Nummers die VIES heeft afgekeurd krijgen in geen van beide standen de vrijstelling.';
$_MODULE['<{vatnumber}prestashop>vatnumber_c3611ab7e05da6ec6a6d66098df71627'] = 'Elke run controleert %d nummers. Om een grote wachtrij sneller weg te werken voegt u &limit=%d aan de URL toe (het maximum per run).';
$_MODULE['<{vatnumber}prestashop>vatnumber_00d23a76e43b46dae9ec7aa9dcbebb32'] = 'Ingeschakeld';
$_MODULE['<{vatnumber}prestashop>vatnumber_8aa92523f0a021be484f930bc2c1d452'] = 'Inschakelen voegt een eenvoudig vinkje voor btw-vrijstellingen toe. Gebruik dit voor btw-vrijstellingen die niet aan een btw-nummer gekoppeld zijn. Een aangevinkt vakje herkent u aan \'%s\' in de back office in het btw-nummerveld onder Klanten -> Adressen.';
$_MODULE['<{vatnumber}prestashop>vatnumber_b25c4046a0e5c918765d51e10d709113'] = 'Vul het volledige nummer in inclusief de tweeletterige landcode, bijvoorbeeld %s. Spaties, punten en streepjes zijn geen probleem. Gebruik EL of GR voor Griekenland en XI voor Noord-Ierland.';
